import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Clash compatibility with mihomo, sing-box, Surge, Quantumult X, Shadowrocket, Stash and Loon","description":"Recommended migration paths for mihomo, sing-box, Surge, Quantumult X, Shadowrocket, Stash and Loon subscriptions, configurations and nodes.","frontmatter":{"title":"Clash compatibility with mihomo, sing-box, Surge, Quantumult X, Shadowrocket, Stash and Loon","description":"Recommended migration paths for mihomo, sing-box, Surge, Quantumult X, Shadowrocket, Stash and Loon subscriptions, configurations and nodes.","head":[["meta",{"name":"keywords","content":"Clash iOS compatibility,mihomo iOS,sing-box nodes,Surge nodes,Quantumult X nodes,Shadowrocket subscription,Stash subscription,Loon subscription,Clash YAML,proxy share links"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I move sing-box nodes to Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Prefer a provider-supplied mihomo YAML subscription or recreate the node in Clash from its protocol parameters.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I move Surge or Quantumult X nodes?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Use a subscription that returns mihomo YAML or add the node from its original server and protocol parameters.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Can I reuse a Shadowrocket subscription in Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes when the provider returns mihomo YAML from its HTTPS subscription URL. Recreate rules and modules with Clash rules and corresponding features.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I use ss:// links or Base64 node lists?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Convert them to mihomo YAML or enter their server, port, credentials and protocol parameters in the Clash node editor.\\"}}]}"]]},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md","lastUpdated":0}`),a={name:`guide/compatibility.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="clash-compatibility-with-popular-proxy-apps" tabindex="-1">Clash compatibility with popular proxy apps <a class="header-anchor" href="#clash-compatibility-with-popular-proxy-apps" aria-label="Permalink to “Clash compatibility with popular proxy apps”">​</a></h1><p><strong>Short answer:</strong> Clash directly reads mihomo-format YAML configurations and HTTPS subscriptions that return mihomo YAML, including standard Clash / mihomo YAML used by Stash. Servers and nodes from sing-box, Surge, Quantumult X, Shadowrocket, or Loon can be reused through a compatible subscription or parameter-based node entry.</p><h2 id="choose-the-app-you-use-now" tabindex="-1">Choose the app you use now <a class="header-anchor" href="#choose-the-app-you-use-now" aria-label="Permalink to “Choose the app you use now”">​</a></h2><table tabindex="0"><thead><tr><th>Current app</th><th>Recommended configuration path</th><th>Node path</th><th>Details</th></tr></thead><tbody><tr><td>Clash / mihomo</td><td>Use standard mihomo YAML directly</td><td>Use directly</td><td><a href="/clash.md/guide/compatibility/mihomo">mihomo compatibility</a></td></tr><tr><td>sing-box</td><td>Obtain a mihomo subscription or prepare YAML</td><td>Add supported protocol parameters</td><td><a href="/clash.md/guide/compatibility/sing-box">sing-box compatibility</a></td></tr><tr><td>Surge</td><td>Obtain a mihomo subscription or recreate nodes</td><td>Shared protocols include Snell</td><td><a href="/clash.md/guide/compatibility/surge">Surge compatibility</a></td></tr><tr><td>Quantumult X</td><td>Use a mihomo subscription</td><td>Parameter-based entry also works</td><td><a href="/clash.md/guide/compatibility/quantumult-x">Quantumult X compatibility</a></td></tr><tr><td>Shadowrocket</td><td>Use a mihomo subscription</td><td>Parameter-based entry also works</td><td><a href="/clash.md/guide/compatibility/shadowrocket">Shadowrocket compatibility</a></td></tr><tr><td>Stash</td><td>Use standard Clash / mihomo YAML directly</td><td>Use directly</td><td><a href="/clash.md/guide/compatibility/stash">Stash compatibility</a></td></tr><tr><td>Loon</td><td>Use a mihomo subscription</td><td>Parameter-based entry also works</td><td><a href="/clash.md/guide/compatibility/loon">Loon compatibility</a></td></tr></tbody></table><h2 id="three-kinds-of-compatibility" tabindex="-1">Three kinds of compatibility <a class="header-anchor" href="#three-kinds-of-compatibility" aria-label="Permalink to “Three kinds of compatibility”">​</a></h2><ol><li><strong>Configuration compatibility</strong> — direct reuse of complete configurations.</li><li><strong>Subscription-format compatibility</strong> — receiving mihomo YAML from an HTTPS subscription.</li><li><strong>Protocol interoperability</strong> — connecting directly to the same server.</li></ol><p>Clash provides broad subscription-format and protocol interoperability. Product-specific settings can be recreated with mihomo YAML, Clash rules, and the corresponding features.</p><h2 id="what-can-clash-import-directly" tabindex="-1">What can Clash import directly? <a class="header-anchor" href="#what-can-clash-import-directly" aria-label="Permalink to “What can Clash import directly?”">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Result</th></tr></thead><tbody><tr><td>mihomo YAML configuration</td><td>Import directly</td></tr><tr><td>Subscription returning mihomo YAML</td><td>Add the URL directly; subscription User-Agent is configurable</td></tr><tr><td>Standalone node links such as <code>ss://</code></td><td>Convert to mihomo YAML or recreate the node from its parameters</td></tr><tr><td>Base64 node list</td><td>Convert to mihomo YAML before import</td></tr><tr><td>QR code containing an HTTPS subscription URL</td><td>Scan to add a remote configuration</td></tr></tbody></table><p>See the <a href="/clash.md/guide/protocols">complete protocol list</a>.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to “Frequently asked questions”">​</a></h2><h3 id="can-i-reuse-my-shadowrocket-subscription" tabindex="-1">Can I reuse my Shadowrocket subscription? <a class="header-anchor" href="#can-i-reuse-my-shadowrocket-subscription" aria-label="Permalink to “Can I reuse my Shadowrocket subscription?”">​</a></h3><p>Yes when the provider returns mihomo-compatible YAML from the HTTPS subscription URL. Recreate Shadowrocket rules, modules, and app settings with Clash rules and the corresponding features. See the dedicated <a href="/clash.md/guide/compatibility/shadowrocket">Shadowrocket compatibility guide</a>.</p><h3 id="can-i-use-the-same-airport-or-provider-subscription" tabindex="-1">Can I use the same airport or provider subscription? <a class="header-anchor" href="#can-i-use-the-same-airport-or-provider-subscription" aria-label="Permalink to “Can I use the same airport or provider subscription?”">​</a></h3><p>Yes, if the provider can return mihomo-compatible YAML. Clash can change its subscription User-Agent for panels that select an output format by client name.</p><h3 id="can-i-keep-using-the-same-server" tabindex="-1">Can I keep using the same server? <a class="header-anchor" href="#can-i-keep-using-the-same-server" aria-label="Permalink to “Can I keep using the same server?”">​</a></h3><p>When the protocol and all required parameters are supported, the same server works directly.</p><h3 id="does-compatibility-mean-affiliation" tabindex="-1">Does compatibility mean affiliation? <a class="header-anchor" href="#does-compatibility-mean-affiliation" aria-label="Permalink to “Does compatibility mean affiliation?”">​</a></h3><p>Brand names identify configuration and protocol compatibility. Clash and Hako are developed and maintained independently.</p>`,19)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};